8	/**
9	 * Rejects a create-owner request whose normalized telephone is already used by any other
10	 * owner, responding 409. Runs after {@link ValidateOwnerFields} (which normalizes the
11	 * telephone to exactly ten digits) and before {@link BuildOwner}, comparing against the
12	 * normalized telephone of every existing owner.
13	 */
14	public class EnsureUniqueOwnerTelephone {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateOwnerTelephoneException {
18	        String telephone = normalize(request.getTelephone());
19	        for (Owner existing : ownerRepository.findAll()) {
20	            if (telephone.equals(normalize(existing.getTelephone()))) {
21	                throw new DuplicateOwnerTelephoneException(telephone);
22	            }
23	        }
24	    }
25	
26	    private static String normalize(String telephone) {
27	        return telephone == null ? "" : telephone.replaceAll("\\D", "");
28	    }
29	}
