2	
3	import java.util.ArrayList;
4	import java.util.List;
5	
6	import net.officefloor.plugin.variable.Out;
7	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
8	import org.springframework.web.bind.annotation.RequestBody;
9	
10	/**
11	 * Rejects a create-owner request that is missing or blank in any of firstName, lastName,
12	 * address, city or telephone, before {@link BuildOwner} runs. Runs first so an incomplete
13	 * body is a 400 naming the offending fields. Also normalizes the telephone by stripping
14	 * every non-digit character and requires exactly ten digits, rejecting otherwise with a
15	 * 400; the normalized value is stored on the body so it is persisted and returned.
16	 * When an {@code email} is present it must be a syntactically valid address and is stored
17	 * lower-cased (rejected with 400 otherwise); an absent email is allowed.
18	 * Publishes the validated body for later steps.
19	 */
20	public class ValidateOwnerFields {
21	
22	    public void service(@RequestBody OwnerFieldsDto request, Out<OwnerFieldsDto> validated)
23	            throws MissingOwnerFieldsException, InvalidOwnerTelephoneException, InvalidOwnerEmailException {
24	        List<String> missing = new ArrayList<>();
25	        checkField("firstName", request.getFirstName(), missing);
26	        checkField("lastName", request.getLastName(), missing);
27	        checkField("address", request.getAddress(), missing);
28	        checkField("city", request.getCity(), missing);
29	        checkField("telephone", request.getTelephone(), missing);
30	        if (!missing.isEmpty()) {
31	            throw new MissingOwnerFieldsException(missing);
32	        }
33	        String telephone = request.getTelephone().replaceAll("\\D", "");
34	        if (telephone.length() != 10) {
35	            throw new InvalidOwnerTelephoneException(telephone);
36	        }
37	        request.setTelephone(telephone);
38	        OwnerEmail.normalize(request);
39	        validated.set(request);
40	    }
41	
42	    private static void checkField(String name, String value, List<String> missing) {
43	        if (value == null || value.isBlank()) {
44	            missing.add(name);
45	        }
46	    }
47	}
